import React from "react";
import Slider from "react-slick";
import "slick-carousel/slick/slick.css";
import "slick-carousel/slick/slick-theme.css";

const EventSlider = () => {
  const settings = {
    dots: true,
    infinite: true,
    speed: 500,
    slidesToShow: 1, // Figma tasarımınız tek bir carousel gösteriyor.
    slidesToScroll: 1,
  };

  return (
    <div
      style={{
        position: "relative",
        width: "1024px",
        height: "394.42px",
        margin: "0 auto",
        background: "#293349", // Lacivert arka plan
        border: "15px solid #00C26D", // Yeşil çerçeve
      }}
    >
      {/* Slider İçeriği */}
      <Slider {...settings}>
        <div
          style={{
            height: "373px",
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            color: "#fff",
            fontSize: "24px",
            fontWeight: "bold",
            background: "#293349",
          }}
        >
          Slide 1
        </div>
        <div
          style={{
            height: "373px",
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            color: "#fff",
            fontSize: "24px",
            fontWeight: "bold",
            background: "#293349",
          }}
        >
          Slide 2
        </div>
        <div
          style={{
            height: "373px",
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            color: "#fff",
            fontSize: "24px",
            fontWeight: "bold",
            background: "#293349",
          }}
        >
          Slide 3
        </div>
      </Slider>

      {/* Kesik Çizgiler ve Dots */}
      <div
        style={{
          position: "absolute",
          top: "10px",
          left: "10px",
          display: "flex",
          flexDirection: "column",
          gap: "10px",
        }}
      >
        {/* Dotlar */}
        <div style={{ width: "30.16px", height: "11.11px", background: "#293349" }}></div>
        <div style={{ width: "30.16px", height: "11.11px", background: "#293349" }}></div>
      </div>
      <div
        style={{
          position: "absolute",
          top: "10px",
          right: "10px",
          display: "flex",
          flexDirection: "row",
          gap: "10px",
        }}
      >
        {/* Kesik Çizgi */}
        <div style={{ width: "142.57px", height: "17.42px", background: "#293349" }}></div>
      </div>
    </div>
  );
};

export default EventSlider;
